<section class="phero"><img class="phero-bg" src="/assets/img/photos/flood-cleanup.webp" srcset="/assets/img/photos/flood-cleanup-640.webp 640w, /assets/img/photos/flood-cleanup.webp 1024w" sizes="100vw" width="1024" height="681" alt="" fetchpriority="high" decoding="async"><div class="wrap phero-in"><nav class="crumbs" aria-label="Breadcrumb"><a href="/">Home</a><span aria-hidden="true">›</span><a href="/policyholder-tools/">Free tools</a><span aria-hidden="true">›</span>Wind vs. Flood Damage Splitter</nav><p class="tag">Free organizer</p><h1>Wind vs. Flood Damage Splitter for Coastal Storm Claims</h1><p class="lede">After a hurricane or nor’easter, the same house can have wind damage and flood damage. List each item, tag the cause and see how the loss divides.</p></div></section>
<section class="sec tool-sec"><div class="wrap">
<div class="tool tool-wide" data-tool="split">
  <div class="tool-head"><span>Wind vs. flood damage splitter</span><i>Organize a mixed coastal loss</i></div>
  <div class="tool-body">
    <div class="tool-in">
      <div class="table-wrap items-table"><table><thead><tr><th scope="col">Damaged item</th><th scope="col">Repair cost ($)</th><th scope="col">Cause</th><th scope="col">Wind share (%)</th><th scope="col"><span class="sr-only">Remove</span></th></tr></thead><tbody>
      <tr><td><input name="item" value="Roof shingles & underlayment" aria-label="Damaged item"></td><td><input name="amt" inputmode="decimal" value="14800" aria-label="Repair cost"></td><td><select name="cause" aria-label="Cause"><option value="wind" selected>Wind / wind-driven rain</option><option value="flood">Flood / storm surge</option><option value="mixed">Mixed — set wind %</option></select></td><td><input name="wpct" inputmode="decimal" value="100" aria-label="Wind share percent"></td><td><button type="button" class="x" aria-label="Remove row">×</button></td></tr><tr><td><input name="item" value="First-floor drywall & flooring" aria-label="Damaged item"></td><td><input name="amt" inputmode="decimal" value="23500" aria-label="Repair cost"></td><td><select name="cause" aria-label="Cause"><option value="wind">Wind / wind-driven rain</option><option value="flood" selected>Flood / storm surge</option><option value="mixed">Mixed — set wind %</option></select></td><td><input name="wpct" inputmode="decimal" value="0" aria-label="Wind share percent"></td><td><button type="button" class="x" aria-label="Remove row">×</button></td></tr><tr><td><input name="item" value="Second-floor ceiling (rain through roof)" aria-label="Damaged item"></td><td><input name="amt" inputmode="decimal" value="3900" aria-label="Repair cost"></td><td><select name="cause" aria-label="Cause"><option value="wind" selected>Wind / wind-driven rain</option><option value="flood">Flood / storm surge</option><option value="mixed">Mixed — set wind %</option></select></td><td><input name="wpct" inputmode="decimal" value="100" aria-label="Wind share percent"></td><td><button type="button" class="x" aria-label="Remove row">×</button></td></tr><tr><td><input name="item" value="Exterior siding" aria-label="Damaged item"></td><td><input name="amt" inputmode="decimal" value="6200" aria-label="Repair cost"></td><td><select name="cause" aria-label="Cause"><option value="wind">Wind / wind-driven rain</option><option value="flood">Flood / storm surge</option><option value="mixed" selected>Mixed — set wind %</option></select></td><td><input name="wpct" inputmode="decimal" value="60" aria-label="Wind share percent"></td><td><button type="button" class="x" aria-label="Remove row">×</button></td></tr>
      </tbody></table></div>
      <div class="btn-row"><button type="button" class="btn line small" data-add data-run>+ Add item</button></div>
      <div class="row2">
        <div><label for="s-cova">Dwelling coverage (Coverage A)</label><input id="s-cova" name="cova" inputmode="decimal" value="420000"></div>
        <div><label for="s-hp">Hurricane deductible</label><select id="s-hp" name="hpct"><option value="0">Not triggered — use standard</option><option value="1">1%</option><option value="2" selected>2%</option><option value="3">3%</option><option value="5">5%</option></select></div>
      </div>
      <div class="row2">
        <div><label for="s-std">Standard homeowner deductible</label><input id="s-std" name="std" inputmode="decimal" value="1000"></div>
        <div><label for="s-fd">Flood policy deductible</label><input id="s-fd" name="fded" inputmode="decimal" value="2000"></div>
